import React, { useState, useRef, useEffect } from 'react';
import {
  Panel,
  Flex,
  Container,
  Typography,
  Button,
} from '@maxhub/max-ui';

const EventCard = ({ event, isRegistered, onRegister, onUnregister, role, onEdit, onDelete, onStats }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef(null);

  const isFull = event.available_seats === 0;
  const instituteName = event.institute_name || 'Все институты';
  const isAdmin = role === 'admin';

  // Закрытие меню при клике вне
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <Panel mode="island" style={{ marginBottom: '12px', position: 'relative' }}>
      {/* Административное меню (оставлено кастомное) */}
      {isAdmin && (
        <div ref={menuRef} style={{ position: 'absolute', top: '8px', right: '8px', zIndex: 10 }}>
          <Button mode="tertiary" size="s" onClick={() => setMenuOpen(!menuOpen)}>
            ⋮
          </Button>
          {menuOpen && (
            <div style={{
              position: 'absolute',
              right: 0,
              top: '100%',
              background: 'var(--max-panel-background, #1e293b)',
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
              overflow: 'hidden',
              minWidth: '140px',
            }}>
              <button onClick={() => { setMenuOpen(false); onEdit(event); }} style={menuItemStyle}>
                ✏️ Редактировать
              </button>
              <button onClick={() => { setMenuOpen(false); onStats(event); }} style={menuItemStyle}>
                📊 Статистика
              </button>
              <button onClick={() => { setMenuOpen(false); onDelete(event); }} style={{ ...menuItemStyle, color: '#ff6b6b' }}>
                🗑️ Удалить
              </button>
            </div>
          )}
        </div>
      )}

      {/* Основной контент */}
      <Flex direction="column" gap={8}>
        <Container>
          <Typography.Headline variant="large-strong" style={{ paddingRight: isAdmin ? '36px' : '0' }}>
            {event.title}
          </Typography.Headline>
        </Container>

        <Typography.Body variant="small">
          {event.category_name} | {event.event_date} {event.event_time}
        </Typography.Body>

        <Typography.Body variant="small">{event.description}</Typography.Body>

        <Typography.Body variant="small">🏛️ {instituteName}</Typography.Body>

        <Flex justify="space-between" style={{ marginTop: '8px' }}>
          <Typography.Body variant="small">📍 {event.location}</Typography.Body>
          <Typography.Body variant="small">
            Мест: {event.available_seats} / {event.capacity}
          </Typography.Body>
        </Flex>

        {/* Кнопки регистрации/отмены */}
        <Container style={{ marginTop: '12px' }}>
          {isRegistered ? (
            <Button
              mode="primary"
              size="l"
              stretched
              style={{ background: '#B22222', color: 'white' }}
              onClick={() => onUnregister(event.id)}
            >
              Отменить запись
            </Button>
          ) : (
            <Button
              mode="primary"
              size="l"
              stretched
              disabled={isFull}
              onClick={() => onRegister(event.id)}
            >
              {isFull ? 'Мест нет' : 'Зарегистрироваться'}
            </Button>
          )}
        </Container>
      </Flex>
    </Panel>
  );
};

const menuItemStyle = {
  display: 'block',
  width: '100%',
  padding: '10px 16px',
  background: 'none',
  border: 'none',
  color: 'var(--max-text-primary, #fff)',
  textAlign: 'left',
  cursor: 'pointer',
};

export default EventCard;